<template><el-drawer v-model="visible" title="详情"><el-descriptions v-if="row" :column="1"><el-descriptions-item v-for="(value, key) in row" :key="key" :label="String(key)"><span v-text="String(value ?? '')" /></el-descriptions-item></el-descriptions></el-drawer></template>
<script setup lang="ts">import { computed } from 'vue'; import type { ProductModel } from '../api'; const props=defineProps<{modelValue:boolean;row:ProductModel|null}>(); const emit=defineEmits<{ 'update:modelValue':[boolean] }>(); const visible=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)});</script>
